edits.before:
if (pointed.kind === "unrecognised-item") {
  this.options.report.itemUnrecognised({ kind: "item-unrecognised", site: "music", source: facts.kind, element: pointed.element })
  return pointed
}

edits.after:
const alternative = await this.options.page.run({ job: { kind: "nowPlaying" } })
return alternative.ok && alternative.data !== null ? { kind: "current-song", song: alternative.data, queueDisposition: "insert-copy" }
  : { kind: "unavailable", failure: alternative.ok ? unavailable : alternative }
